"use strict";(self.webpackChunkwiki_en=self.webpackChunkwiki_en||[]).push([["16689"],{62332(e){e.exports=JSON.parse('{"tag":{"label":"Jetson","permalink":"/tags/jetson","allTagsPath":"/tags","count":7,"items":[{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/reComputer_Robotics_Getting_Started","title":"Getting Started with reComputer Robotics","description":"The reComputer Robotics J401 is a high-performance edge AI carrier board designed for advanced robotics applications. It supports NVIDIA Jetson Orin Nano and Orin NX modules in Super/MAXN mode, delivering up to 157 TOPS of AI computing power. The board offers extensive connectivity options, including dual Gigabit Ethernet, multiple USB 3.2 ports, CAN, M.2 slots for 5G/Wi-Fi/BT modules, and optional GMSL2 camera support. Pre-installed with JetPack 6, it ensures seamless deployment for robotics development. The rugged design supports wide operating temperatures and includes a pre-installed heatsink with fan. The setup involves flashing the JetPack OS onto an NVMe SSD using a compatible Ubuntu host PC, followed by hardware configuration and interface usage. Detailed hardware specifications, mechanical drawings, and technical resources are provided for developers, along with community and technical support channels for troubleshooting and discussion.","permalink":"/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/J501/Hardware_Interfaces_Usage","title":"Interfaces Usage","description":"Hardware and Interfaces Usage for J501 carrier board","permalink":"/j501_carrier_board_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J401 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, UART, I2C, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J401 platform.","permalink":"/recomputer_jetson_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J601/Robotics_J601_carrierboard_Hardware_Interfaces_Usage","title":"Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J601 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, RS485/RS232, UART, I2C, I2S, GPIO, GMSL2 camera expansion, 5G, and GPS, helping users quickly get started with robotics development on the J601 platform.","permalink":"/recomputer_jetson_robotics_j601_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/reComputer_Robotics_Hardware_Interfaces_Usage","title":"reComputer Robotics Hardware and Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J401 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, UART, I2C, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J401 platform.","permalink":"/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super vs Classic Next-Gen AI Performance in Edge Inferencing","description":"This article highlights the superior AI performance of the reComputer Super compared to the reComputer Classic, demonstrating up to a 1.7x boost in AI compute power with the NVIDIA Jetson Orin NX 16GB. Through practical benchmarks in AI text generation using the DeepSeek-R1:7B model with Ollama, and AI video processing using the YOLOv11 object detection model, the results show that the reComputer Super delivers significantly faster inference speeds and higher GPU frequencies. Notably, it processes approximately 2.37 times more images per second than the Classic. The article also explains the importance of evaluating performance based on terminal-reported FPS rather than on-screen FPS, which can be limited by display and system factors.","permalink":"/recomputer_jetson_super_performance"},{"id":"Edge/NVIDIA_Jetson/Application/Computer_Vision/Streaming_Vision_Agent_on_Jetson","title":"Streaming Vision Agent on Jetson","description":"Deploy a Streaming Vision Agent on NVIDIA Jetson with dual Qwen3-VL-2B rolling multimodal memory and live Ask UI","permalink":"/streaming_vision_agent_on_jetson"}],"unlisted":false}}')}}]);